# Too easy or too plain: never used even if listed above.
EASY = set("""pizza taco burrito pancake stack cupcake doughnut popcorn lollipop pineapple coconut avocado mango plum
raspberry blackberry pumpkin mushroom celery radish tortilla teddy bear balloon flag tent campfire umbrella suitcase
backpack sunglasses toothbrush ruler eraser envelope calculator whiteboard blackboard chalk bucket broom mop mirror
curtain sink bathtub vase flowerpot kettle teapot toaster blender wok saucepan whisk spatula dolphin polar crocodile
alligator gorilla chimpanzee fox goat donkey hen rooster goose sparrow robin parrot hoodie gloves scarf sandals
raincoat apron crown helmet sunflower tulip daisy dandelion cactus waterfall volcano rainbow tornado glacier iceberg
cave castle pyramid fountain statue monument tower balcony chimney tunnel ferry helicopter tractor ambulance skateboard
snowboard skis trophy medal dumbbell surfboard fountain dartboard thermometer syringe bandage wheelchair headphones
microphone projector jukebox sword shield dagger spear pony ram cheetah lizard dolphin ostrich owl swan penguin
hamburger sandwich balloon candle bed chair table clock lamp piano guitar violin drum trumpet flute""".split())
EASY_PHRASES = {"polar bear", "teddy bear", "pancake stack", "party balloon", "bald eagle", "fire engine", "school bus",
                "sleeping bag", "chess board", "jigsaw puzzle", "palm tree", "alligator", "piano accordion"}
QUALIFIERS = {"bird", "game", "tool", "school", "wooden", "antique", "desk", "sand", "brass", "pirate", "medical",
              "hiking", "lamp", "castle", "dutch", "farm", "robe", "toy", "bar", "classroom", "church", "blacksmith",
              "fireplace", "garden", "submarine", "wheel", "player", "vintage", "pharmacy", "floats", "weapon"}


def _ok(word: str) -> bool:
    toks = word.split()
    if len(toks) > 2 or len(word) < 3 or len(word) > 24:
        return False
    if word in EASY_PHRASES or (len(toks) == 1 and word in EASY):
        return False
    if len(toks) == 2 and toks[1] in QUALIFIERS:
        return False
    if len(toks) == 2 and any(t in {"and", "of", "in", "the", "a"} for t in toks):
        return False
    return True


def _parse() -> list:
    out, seen = [], set()
    for block in _BLOCKS:
        cat, diff, body = block.split("|", 2)
        for part in body.split(","):
            part = part.strip()
            if not part:
                continue
            word, _, query = part.partition(":")
            word = word.strip().lower()
            query = query.strip().lower() or word
            if not word or word in seen or not _ok(word):
                continue
            seen.add(word)
            out.append((word, query, cat.strip(), int(diff)))
    return out


WORDBANK = _parse()
